import * as api from '/atlas-api.js';
const root=document.querySelector('#workspace');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let configuration,identity=api.currentIdentity(),plans=[],contents=[],editor=null,loadedUser=null,busy=false;
let toastTimer;
function status(message,error=false){const node=document.querySelector('#workspace-status');node.textContent=message;node.classList.toggle('workspace-error',error);node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{node.hidden=true;},7000);}
function message(error){if(error.code==='40001')return '这份计划已在其他页面更新，请重新打开后再保存。';return error.message||'操作未完成，请重试。';}
function newPlan(){return {title:'',notes:'',days:[{title:'训练日 1',items:[]}]};}
function row(item,dayIndex,itemIndex){const p=item.prescription??{};const title=contents.find(x=>x.id===item.content_id)?.title??item.snapshot_title??'已下架动作';return `<div class="plan-item"><div class="workspace-row"><strong>${esc(title)}</strong><span><button type="button" class="workspace-icon-button" data-action="up-item" data-day="${dayIndex}" data-item="${itemIndex}" aria-label="上移动作">↑</button> <button type="button" class="workspace-icon-button" data-action="down-item" data-day="${dayIndex}" data-item="${itemIndex}" aria-label="下移动作">↓</button> <button type="button" class="workspace-icon-button" data-action="remove-item" data-day="${dayIndex}" data-item="${itemIndex}">移除</button></span></div><div class="plan-item-fields">${[['sets','组数'],['reps','每组次数'],['load_kg','负重（kg）'],['rest_seconds','休息（秒）']].map(([key,label])=>`<label>${label}<input data-field="parameter" data-key="${key}" data-day="${dayIndex}" data-item="${itemIndex}" type="number" min="${['sets','reps'].includes(key)?1:0}" step="${['sets','reps','rest_seconds'].includes(key)?1:'any'}" value="${esc(p[key]??'')}" placeholder="自行填写"></label>`).join('')}</div><label class="workspace-small">动作备注<input data-field="item-notes" data-day="${dayIndex}" data-item="${itemIndex}" maxlength="1000" value="${esc(p.notes??'')}" placeholder="可选"></label></div>`;}
function editorMarkup(){if(!editor)return '<section class="workspace-card"><h2>建立自己的训练计划</h2><p>选择已有计划，或新建一份安排。计划只对你的账号可见。</p><button class="button primary" data-action="new-plan">新建计划 ＋</button></section>';return `<section class="workspace-card"><div class="workspace-row"><h2>${editor.id?'编辑计划':'新建计划'}</h2><span class="workspace-pill">仅自己可见</span></div><form id="plan-form"><label for="plan-title">计划名称</label><input id="plan-title" data-field="title" maxlength="120" required value="${esc(editor.title)}" placeholder="给这份安排取个名字"><label for="plan-notes">计划备注</label><textarea id="plan-notes" data-field="notes" maxlength="4000">${esc(editor.notes)}</textarea><div class="workspace-warning">当前动作库包含待专业审核的 3D 样本，可用于体验计划编辑；训练参数由你自行填写。</div>${editor.days.map((day,i)=>`<section class="workspace-day"><div class="workspace-row"><input aria-label="训练日名称" data-field="day-title" data-day="${i}" maxlength="100" required value="${esc(day.title)}"><button type="button" class="workspace-icon-button" data-action="remove-day" data-day="${i}">移除训练日</button></div>${day.items.map((item,j)=>row(item,i,j)).join('')}<label>添加动作<select id="exercise-${i}" aria-label="为训练日选择动作">${contents.filter(x=>x.content_type==='exercise').map(item=>`<option value="${esc(item.id)}">${esc(item.title)}${item.review_status==='prototype'?' · 样本':''}</option>`).join('')}</select></label><button type="button" class="workspace-icon-button" data-action="add-item" data-day="${i}" ${contents.length?'':'disabled'}>加入此训练日 ＋</button></section>`).join('')}<div class="workspace-actions"><button type="button" class="button outline" data-action="add-day" ${editor.days.length>=14?'disabled':''}>添加训练日 ＋</button><button class="button primary" type="submit" ${busy?'disabled':''}>${busy?'正在保存…':'保存计划'}</button>${editor.id?'<button type="button" class="button outline workspace-danger" data-action="delete-plan">删除计划</button>':''}</div></form></section>`;}
function render(){
  if(!identity.user){root.innerHTML=`<section class="workspace-card"><h2>你的安排，跟着账号一起保存。</h2><p>使用 Google 账号创建或登录网站账号，保存个人计划并在下次访问时继续编辑。</p><div class="workspace-actions"><button class="button primary" data-action="login" ${configuration?.googleEnabled?'':'disabled'}>使用 Google 继续 ↗</button><a class="button outline" href="/library">先浏览动作资料</a></div>${configuration?.googleEnabled?'':'<p class="workspace-small">Google 登录尚在配置中，暂未开放。</p>'}${identity.error?`<p class="workspace-error">${esc(identity.error)}</p>`:''}</section>`;return;}
  if(identity.access?.account_status==='suspended'){root.innerHTML='<section class="workspace-card"><h2>账号暂不可用</h2><p>你仍可浏览公开资料。如需恢复账号，请联系管理员。</p><button class="button outline" data-action="logout">退出登录</button></section>';return;}
  root.innerHTML=`<section class="workspace-card"><div class="workspace-row"><div><span class="eyebrow">SIGNED IN</span><h2>${esc(identity.profile?.display_name||identity.user.email)}</h2><p>${esc(identity.user.email)}</p></div><div class="workspace-actions">${identity.access?.role==='admin'?'<a class="button outline" href="/admin/index.html">内容与账号管理 ↗</a>':''}<button class="button outline" data-action="logout">退出登录</button></div></div><details><summary>个人资料</summary><form id="profile-form"><div class="workspace-two"><label>显示名称<input name="display_name" maxlength="100" value="${esc(identity.profile?.display_name)}"></label><label>时区<input name="timezone" maxlength="100" value="${esc(identity.profile?.timezone??'Asia/Tokyo')}" placeholder="Asia/Tokyo"></label></div><button class="button outline" type="submit">保存资料</button></form></details></section><div class="workspace-grid"><aside class="workspace-card"><div class="workspace-row"><h3>我的计划</h3><button class="workspace-icon-button" data-action="new-plan">＋ 新建</button></div><div class="workspace-list" style="margin-top:16px">${plans.length?plans.map(plan=>`<button data-action="select-plan" data-id="${esc(plan.id)}" class="${editor?.id===plan.id?'selected':''}">${esc(plan.title)}<small>${plan.days.length} 个训练日 · ${new Date(plan.updated_at).toLocaleDateString('zh-CN')}</small></button>`).join(''):'<p>还没有保存的计划。</p>'}</div></aside>${editorMarkup()}</div>`;
}
async function loadUserData(){if(!identity.user||identity.access?.account_status!=='active'){render();return;}const userId=identity.user.id;try{const [nextPlans,nextContents]=await Promise.all([api.listPlans(),api.listPublishedContent()]);if(identity.user?.id!==userId)return;plans=nextPlans;contents=nextContents;const pending=new URLSearchParams(location.search).get('add')||sessionStorage.getItem('jy-pending-content');if(pending&&contents.some(x=>x.id===pending)){editor=newPlan();editor.days[0].items.push({content_id:pending,prescription:{}});sessionStorage.removeItem('jy-pending-content');history.replaceState(null,'',location.pathname);status('动作已加入新计划，填写名称后即可保存。');}render();api.recordActivity('page_view','/account');}catch(error){status(message(error),true);root.innerHTML=`<section class="workspace-card"><h2>计划暂时无法读取</h2><p class="workspace-error">${esc(message(error))}</p><button class="button outline" data-action="retry">重试</button></section>`;}}
root.addEventListener('input',event=>{if(!editor)return;const c=event.target;const day=editor.days[Number(c.dataset.day)];const item=day?.items[Number(c.dataset.item)];if(c.dataset.field==='title')editor.title=c.value;if(c.dataset.field==='notes')editor.notes=c.value;if(c.dataset.field==='day-title')day.title=c.value;if(c.dataset.field==='parameter'){item.prescription??={};if(c.value==='')delete item.prescription[c.dataset.key];else item.prescription[c.dataset.key]=Number(c.value);}if(c.dataset.field==='item-notes'){item.prescription??={};item.prescription.notes=c.value;}});
root.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button||busy)return;const a=button.dataset.action;try{
  if(a==='login'){const add=new URLSearchParams(location.search).get('add');if(add)sessionStorage.setItem('jy-pending-content',add);await api.signInWithGoogle();return;}
  if(a==='logout'){await api.signOut();editor=null;plans=[];return;}
  if(a==='retry'){await loadUserData();return;}
  if(a==='new-plan')editor=newPlan();
  if(a==='select-plan'){if(editor&&!confirm('打开这份计划？当前未保存的修改将被放弃。'))return;editor=structuredClone(plans.find(x=>x.id===button.dataset.id));}
  const i=Number(button.dataset.day),j=Number(button.dataset.item);
  if(a==='add-day')editor.days.push({title:`训练日 ${editor.days.length+1}`,items:[]});
  if(a==='remove-day'){if(editor.days.length===1)throw new Error('至少保留一个训练日');editor.days.splice(i,1);}
  if(a==='add-item'){const id=root.querySelector(`#exercise-${i}`).value;if(!id)throw new Error('当前没有可添加的动作');editor.days[i].items.push({content_id:id,prescription:{}});}
  if(a==='remove-item')editor.days[i].items.splice(j,1);
  if(a==='up-item'&&j>0)[editor.days[i].items[j-1],editor.days[i].items[j]]=[editor.days[i].items[j],editor.days[i].items[j-1]];
  if(a==='down-item'&&j<editor.days[i].items.length-1)[editor.days[i].items[j+1],editor.days[i].items[j]]=[editor.days[i].items[j],editor.days[i].items[j+1]];
  if(a==='delete-plan'){if(!confirm('删除这份计划？此操作无法恢复。'))return;await api.deletePlan(editor.id);editor=null;plans=await api.listPlans();status('计划已删除。');}
  render();
}catch(error){status(message(error),true);}});
root.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;busy=true;try{if(event.target.id==='profile-form'){const values=new FormData(event.target);await api.updateProfile(Object.fromEntries(values));status('个人资料已保存。');}if(event.target.id==='plan-form'){const saved=await api.savePlan(editor);plans=await api.listPlans();editor=structuredClone(plans.find(x=>x.id===saved.id));status('计划已保存到你的账号。');}}catch(error){status(message(error),true);}finally{busy=false;render();}});
try{configuration=await api.initializeBackend();api.subscribeIdentity(next=>{identity=next;if(next.user?.id!==loadedUser){loadedUser=next.user?.id??null;editor=null;plans=[];if(next.user)loadUserData();else render();}else render();});}catch(error){root.innerHTML=`<section class="workspace-card"><h2>账户服务暂不可用</h2><p class="workspace-error">${esc(error.message)}</p><div class="workspace-actions"><button class="button outline" onclick="location.reload()">重新加载</button><a class="button outline" href="/">返回探索</a></div></section>`;}
